 if(flag.HasValue)p.GetType().GetProperty("RefreshFlag").SetValue(p,new List<int>{flag.Value},null);if(count.HasValue)p.GetType().GetProperty("BufferCount").SetValue(p,new List<int>{count.Value},null);
