 Run(module,"defaults",null,null,10);for(int i=0;i<6;i++)Run(module,"three-"+i,1,3,20+i*10);Run(module,"hold",0,3,90);Run(module,"hold-shrink",0,1,95);Run(module,"hold-zero",0,0,96);Run(module,"negative-flag",-1,3,110);Run(module,"flag-two",2,3,120);foreach(int n in new[]{1,2,5,0,-1,15,16,100})Run(module,"count-"+n,1,n,130+n);Run(module,"rgb",1,3,180,3);Run(module,"resize",1,3,190,1,4,4);Run(module,"after-resize",1,3,200);for(int i=0;i<18;i++)Run(module,"fill-fifteen-"+i,1,15,210+i);foreach(int format in new[]{1,2,3,200,201,35127329,12345})Run(module,"format-"+format,1,3,52,format==1?1:3,8,8,format);foreach(int format in new[]{1,2,3,200,201,12345})Run(module,"raw-format-"+format,1,3,62,3,8,8,format,true);Attempt("sdk-ui",()=>Ui(module,Get(module,"ModuParams"),output));Attempt("persistence",delegate{string full=Convert.ToString(Get(proc,"Name"))+"."+Convert.ToString(Get(module,"Name"));string saved=Path.Combine(output,"owned-buffer.sol");st.GetMethod("SaveAs",new[]{typeof(string),typeof(string)}).Invoke(null,new object[]{saved,null});Attempt("reload",()=>st.GetMethod("Load",new[]{typeof(string),typeof(string),typeof(bool)}).Invoke(null,new object[]{saved,"",false}));solution=st.GetProperty("Instance").GetValue(null,null);var restored=st.GetProperty("Item").GetValue(solution,new object[]{full});Run(restored,"reloaded-cache-empty",0,15,1);});rows.Add(new{phase="finished",parityEstablished=false});
